/**
 * Shared helper for media-generating plugins: write generated bytes to a
 * file and return its path, instead of returning raw base64.
 *
 * Base64 payloads in an action result bloat the agent context and are
 * stripped by many hosts before reaching the model, so the agent can never
 * actually deliver the file. A file `path` hands straight to a host
 * send_file/attachment tool. Plugins load in-process via jiti, so node:fs is
 * available (same pattern as googleDrive/googleSlides).
 */
import { basename, extname } from "node:path";
import { readLocalFile, writeOutputFile } from "@shiftlabs/codemode";

const MIME_EXT: Record<string, string> = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/jpg": "jpg",
  "image/webp": "webp",
  "image/gif": "gif",
  "image/svg+xml": "svg",
  "video/mp4": "mp4",
  "video/webm": "webm",
  "video/quicktime": "mov",
  "audio/mpeg": "mp3",
  "audio/mp3": "mp3",
  "audio/wav": "wav",
  "audio/x-wav": "wav",
  "audio/ogg": "ogg",
  "audio/opus": "opus",
  "audio/x-pcm": "pcm",
};

export function extForMime(mimeType: string | undefined): string {
  if (!mimeType) return "png";
  const mime = mimeType.split(";")[0].trim().toLowerCase();
  return Object.hasOwn(MIME_EXT, mime) ? MIME_EXT[mime] : "bin";
}

export interface SavedMedia {
  path: string;
  mimeType: string;
  byteLength: number;
}

/** What every media action says of its `saveDir` input. */
export const SAVE_DIR_DESCRIPTION =
  "Existing directory to write the file(s) into. Empty or omitted uses the host's output directory, else the system's temporary directory.";

/**
 * Where an action writes its media: the directory its caller asked for,
 * else the one the host keeps output files in.
 */
export function mediaDir(
  asked: string | undefined,
  ctx: { outputDir?: string },
): string | undefined {
  return (typeof asked === "string" && asked.trim()) || ctx.outputDir;
}

/**
 * Write media bytes to an output file of their own in `saveDir`, which an
 * action takes from `mediaDir()`.
 */
export function writeMediaFile(opts: {
  bytes: Uint8Array;
  mimeType?: string;
  provider: string;
  index: number;
  saveDir?: string;
  stamp?: number;
}): SavedMedia {
  const mimeType = opts.mimeType ?? "image/png";
  const stamp = opts.stamp ?? Date.now();
  if (!/^[\w-]+$/.test(opts.provider))
    throw new Error("invalid media provider name");
  const path = writeOutputFile(
    `${opts.provider}-${stamp}-${opts.index}`,
    `.${extForMime(mimeType)}`,
    opts.bytes,
    opts.saveDir || undefined,
  );
  return { path, mimeType, byteLength: opts.bytes.byteLength };
}

/**
 * Decode base64 media bytes and write them, for the providers that answer
 * with base64 rather than a URL to download.
 */
export function writeImageFile(opts: {
  base64: string;
  mimeType?: string;
  provider: string;
  index: number;
  saveDir?: string;
  stamp?: number;
}): SavedMedia {
  const { base64, ...rest } = opts;
  return writeMediaFile({
    ...rest,
    bytes: Buffer.from(base64 ?? "", "base64"),
  });
}

export const SEND_FILE_NOTE =
  "File(s) written to disk. Deliver each to the user with send_file using its `path`.";

const EXT_MIME: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp",
  gif: "image/gif",
};

export interface LoadedImage {
  bytes: Buffer<ArrayBuffer>;
  base64: string;
  mimeType: string;
  dataUri: string;
  fileName: string;
}

/** Larger than any provider accepts inline; a data URI past it only fails remotely. */
const MAX_IMAGE_BYTES = 50 * 1024 * 1024;

/**
 * Read a local image for an `image.edit` call: bytes + base64 + mime
 * (from the extension) + a `data:` URI for JSON APIs. Errors carry the
 * plugin's name so they point at the right tool.
 */
export async function readImageInput(
  imagePath: string,
  pluginName: string,
): Promise<LoadedImage> {
  if (typeof imagePath !== "string" || imagePath.trim().length === 0) {
    throw new Error(`${pluginName}: imagePath is required`);
  }
  const bytes = await readLocalFile(imagePath, {
    subject: `${pluginName}: imagePath`,
    maxBytes: MAX_IMAGE_BYTES,
    oversize: `${pluginName}: imagePath exceeds ${MAX_IMAGE_BYTES / (1024 * 1024)} MiB`,
  });
  const ext = extname(imagePath).slice(1).toLowerCase();
  const mimeType = EXT_MIME[ext] ?? "image/png";
  const base64 = bytes.toString("base64");
  return {
    bytes,
    base64,
    mimeType,
    dataUri: `data:${mimeType};base64,${base64}`,
    fileName: basename(imagePath),
  };
}
